#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<vector<long long>> men(n, vector<long long>(n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> men[i][j];
        }
    }
    vector<vector<long long>> women(n, vector<long long>(n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> women[i][j];
        }
    }

    vector<vector<int>> rank(n + 1, vector<int>(n + 1, 0));
    for (int w = 1; w <= n; w++) {
        for (int position = 0; position < n; position++) rank[w][women[w - 1][position]] = position;
    }
    vector<int> nxt(n + 1, 0), partner(n + 1, 0), freeMen;
    for (int m = (int)n; m >= 1; m--) freeMen.push_back(m);
    while (!freeMen.empty()) {
        int m = freeMen.back();
        freeMen.pop_back();
        int w = (int)men[m - 1][nxt[m]];
        nxt[m]++;
        if (partner[w] == 0) {
            partner[w] = m;
        } else if (rank[w][m] < rank[w][partner[w]]) {
            freeMen.push_back(partner[w]);
            partner[w] = m;
        } else {
            freeMen.push_back(m);
        }
    }
    vector<int> wife(n + 1, 0);
    for (int w = 1; w <= n; w++) wife[partner[w]] = w;
    for (int m = 1; m <= n; m++) cout << (m > 1 ? " " : "") << wife[m];
    cout << "\n";

    return 0;
}

